import{_ as o,a as r,b as s,c as n,d as i,e as a,f as e,g,h as l,i as p}from"./chunks/insert-object-stamp.Clcr9d71.js";import{_ as m,o as c,c as d,a2 as h}from"./chunks/framework.Bzj1XTnB.js";const x=JSON.parse('{"title":"तस्वीर, वीडियो, ऑब्जेक्ट और कैनवास के बाहर ड्रॉइंग","description":"फ़ोटो और वीडियो लाएँ, तैयार कैरेक्टर इस्तेमाल करें, अपने सेव करें, और कैनवास के आसपास की जगह में ड्रॉ करें।","frontmatter":{"lang":"hi","slug":"images-video-objects","order":7,"title":"तस्वीर, वीडियो, ऑब्जेक्ट और कैनवास के बाहर ड्रॉइंग","description":"फ़ोटो और वीडियो लाएँ, तैयार कैरेक्टर इस्तेमाल करें, अपने सेव करें, और कैनवास के आसपास की जगह में ड्रॉ करें।"},"headers":[],"relativePath":"hi/images-video-objects.md","filePath":"hi/images-video-objects.md"}'),u={name:"hi/images-video-objects.md"};function _(b,t,f,q,P,j){return c(),d("div",null,[...t[0]||(t[0]=[h('<h1 id="तस्वीर-वीडियो-ऑब्जेक्ट-और-कैनवास-के-बाहर-ड्रॉइंग" tabindex="-1">तस्वीर, वीडियो, ऑब्जेक्ट और कैनवास के बाहर ड्रॉइंग <a class="header-anchor" href="#तस्वीर-वीडियो-ऑब्जेक्ट-और-कैनवास-के-बाहर-ड्रॉइंग" aria-label="Permalink to &quot;तस्वीर, वीडियो, ऑब्जेक्ट और कैनवास के बाहर ड्रॉइंग&quot;">​</a></h1><h2 id="तस्वीर-या-वीडियो-जोड़ें" tabindex="-1">तस्वीर या वीडियो जोड़ें <a class="header-anchor" href="#तस्वीर-या-वीडियो-जोड़ें" aria-label="Permalink to &quot;तस्वीर या वीडियो जोड़ें&quot;">​</a></h2><p>नीचे की पट्टी में <strong>Image/Video</strong> टैप करें।</p><p><img src="'+o+'" alt="तस्वीर या वीडियो जोड़ें"></p><ul><li><strong>Photos</strong> — एक तस्वीर चुनें, या एक साथ कई (30 तक)।</li><li><strong>Videos</strong> — किसी क्लिप को फ़्रेम में बदलें।</li><li><strong>Photo camera</strong> / <strong>Video camera</strong> — अभी फ़ोटो खींचें या क्लिप रिकॉर्ड करें।</li><li><strong>File</strong> — Google Drive, Downloads या किसी दूसरे ऐप से।</li></ul><p>एक तस्वीर कैनवास पर चुने हुए रूप में आती है: उसे हिलाएँ, बड़ा-छोटा करें, <strong>Crop</strong> करें, फिर रखने के लिए बाहर टैप करें।</p><p><strong>कई तस्वीरें</strong> चुनने पर Toonik पूछता है:</p><ul><li><strong>One per frame</strong> — हर तस्वीर अपने अलग फ़्रेम पर। फ़ोटो से स्टॉप-मोशन एनिमेशन बनाने के लिए बढ़िया।</li><li><strong>All on this frame</strong> — सब मौजूदा फ़्रेम पर अगल-बगल, एक साथ सजाने के लिए।</li></ul><h3 id="वीडियो-इम्पोर्ट-करना" tabindex="-1">वीडियो इम्पोर्ट करना <a class="header-anchor" href="#वीडियो-इम्पोर्ट-करना" aria-label="Permalink to &quot;वीडियो इम्पोर्ट करना&quot;">​</a></h3><p><img src="'+r+'" alt="वीडियो इम्पोर्ट"></p><ul><li>क्लिप का हिस्सा चुनने के लिए पट्टी के सिरे खींचें (<strong>Start</strong> और <strong>End</strong>)।</li><li><strong>Import as</strong> — <strong>Animation</strong> (कई फ़्रेम) या <strong>Single frame</strong> (एक तस्वीर)।</li><li><strong>Look</strong> — <strong>Original</strong>, <strong>Line art</strong> (वीडियो को बनी हुई लकीरों में बदलता है; <strong>Clean</strong>, <strong>Medium</strong> या <strong>Rich</strong> डिटेल चुनें) या <strong>Trace guide</strong> (एक हल्की, लॉक लेयर और उसके ऊपर खाली &quot;Ink&quot; लेयर, ताकि वीडियो के ऊपर ट्रेस कर सकें)।</li><li><strong>Timing</strong> — <strong>On ones</strong> या <strong>On twos</strong>।</li></ul><p>वीडियो मौजूदा फ़्रेम से शुरू होकर एक नई लेयर पर आता है। लंबी क्लिप से बहुत सारे फ़्रेम बनते हैं, इसलिए सिर्फ़ ज़रूरी हिस्सा चुनें।</p><h2 id="कैनवास-के-बाहर-ड्रॉ-करें" tabindex="-1">कैनवास के बाहर ड्रॉ करें <a class="header-anchor" href="#कैनवास-के-बाहर-ड्रॉ-करें" aria-label="Permalink to &quot;कैनवास के बाहर ड्रॉ करें&quot;">​</a></h2><p>नए प्रोजेक्ट में <strong>कैनवास के चारों ओर जगह</strong> होती है: कोई कैरेक्टर स्क्रीन के बाहर बनाकर उसे अंदर चलाकर लाएँ, या कैमरा मूव के लिए चौड़ा बैकग्राउंड बनाएँ। मूवी में सिर्फ़ कैनवास के अंदर का हिस्सा आता है।</p><p><img src="'+s+'" alt="कैनवास के आसपास की जगह में ड्रॉइंग"></p><p>कितनी जगह है यह देखने के लिए ज़ूम आउट करें — डैश वाली लाइन उसका किनारा है:</p><p><img src="'+n+'" alt="ज़ूम आउट"></p><p>इसे <strong>⋮ → Project settings → Draw outside the canvas</strong> में चालू या बंद करें। बंद करने पर कैनवास के बाहर बनी हर चीज़ हर फ़्रेम से कट जाती है (पहले पूछा जाता है)।</p><h3 id="जगह-बड़ी-या-छोटी-करें" tabindex="-1">जगह बड़ी या छोटी करें <a class="header-anchor" href="#जगह-बड़ी-या-छोटी-करें" aria-label="Permalink to &quot;जगह बड़ी या छोटी करें&quot;">​</a></h3><p>जब यह चालू हो, स्विच के नीचे <strong>Room size</strong> से जगह की चौड़ाई और ऊँचाई तय करें:</p><p><img src="'+i+'" alt="Room size"></p><ul><li><strong>Width</strong> या <strong>Height</strong> खींचें, या हर तरफ़ 10 px बदलने के लिए <strong>−</strong> और <strong>+</strong> टैप करें। <strong>Automatic</strong> Toonik का चुना हुआ साइज़ वापस लाता है, <strong>Current</strong> अभी वाला।</li><li>प्रीव्यू में आपकी ड्रॉइंग अपनी जगह रहती है, नया किनारा गुलाबी दिखता है, और जो कटेगा वह लाल में। कुछ भी कटने से पहले पूछा जाता है।</li><li>हर फ़्रेम की हर लेयर इस साइज़ की एक तस्वीर होती है, इसलिए जगह मेमोरी लेती है: <strong>Memory</strong> बताता है कितनी। जब एक तरफ़ आपके फ़ोन की सीमा तक पहुँच जाए, तो आगे बढ़ाने के लिए दूसरी तरफ़ छोटी करें। ज़्यादा मेमोरी वाले फ़ोन और टैबलेट को ज़्यादा जगह मिलती है।</li><li><strong>Apply</strong> टैप करें। जगह बदलना Undo नहीं हो सकता और Undo की हिस्ट्री साफ़ हो जाती है।</li></ul><h2 id="object-library" tabindex="-1">Object library <a class="header-anchor" href="#object-library" aria-label="Permalink to &quot;Object library&quot;">​</a></h2><p>तैयार ड्रॉइंग और एनिमेशन जिन्हें किसी भी प्रोजेक्ट में डाल सकते हैं, और आपकी ख़ुद सेव की हुई हर चीज़। इसे एडिटर में <strong>गुलाबी हीरे</strong> से या होम स्क्रीन पर <strong>Objects</strong> से खोलें।</p><p><img src="'+a+'" alt="ऑब्जेक्ट लाइब्रेरी"></p><ul><li><strong>Built-in ऑब्जेक्ट</strong> — चलने और दौड़ने की साइकिल, उछलती गेंद, कूदता इंसान, लोमड़ी, पंख फड़फड़ाती चिड़िया, आगे-पीछे-बगल से दिखते इंसान और जानवर (कुत्ता, बिल्ली, चिड़िया, खरगोश, पांडा, मछली), पेड़, बाँस, चट्टानें, बादल, सूरज, चाँद, तारे, घर, बीच बॉल और कार।</li><li><strong>फ़िल्टर</strong> — All, Static, Animated, Favourites, Built-in। <strong>🔍</strong> नाम या टैग से ढूँढता है।</li><li>किसी ऑब्जेक्ट पर टैप करें — उसकी जानकारी देखें, उसे <strong>favourites</strong> में जोड़ें, या built-in को <strong>duplicate</strong> करें ताकि उसे बदल सकें।</li></ul><p><img src="'+e+'" alt="ऑब्जेक्ट की जानकारी"></p><p>एडिटर से खोलने पर लाइब्रेरी <strong>Insert object</strong> के रूप में खुलती है — जोड़ने के लिए किसी ऑब्जेक्ट पर टैप करें:</p><p><img src="'+g+'" alt="ऑब्जेक्ट जोड़ना"></p><p>प्रोजेक्ट में ऑब्जेक्ट जोड़ते समय आप:</p><ul><li><p><strong>Place</strong> — उसका एक फ़्रेम कैनवास पर चुने हुए रूप में रखें।</p><p><img src="'+l+'" alt="ऑब्जेक्ट रखना"></p></li><li><p><strong>Stamp</strong> (एनिमेटेड ऑब्जेक्ट) — उसका पूरा एनिमेशन आपके फ़्रेम पर बनाएँ, जितनी बार चाहें दोहराकर, मौजूदा लेयर या नई लेयर पर।</p><p><img src="'+p+'" alt="एनिमेशन स्टैम्प करना"></p></li><li><p><strong>Animate</strong> — अपनी चुनी हरकत से उसे कैनवास पर चलाएँ, <em>चुनाव को एनिमेट करें</em> की तरह।</p></li></ul><h3 id="अपने-ऑब्जेक्ट-सेव-करें" tabindex="-1">अपने ऑब्जेक्ट सेव करें <a class="header-anchor" href="#अपने-ऑब्जेक्ट-सेव-करें" aria-label="Permalink to &quot;अपने ऑब्जेक्ट सेव करें&quot;">​</a></h3><p>लैसो से ड्रॉइंग चुनें (या पूरी लेयर, या फ़्रेम की एक रेंज), फिर <strong>⋮ → Save as object</strong>। नाम और टैग दें ताकि बाद में आसानी से मिले।</p>',33)])])}const A=m(u,[["render",_]]);export{x as __pageData,A as default};
